def transform(grid):
    h0, w0 = len(grid), len(grid[0])
    ones = [(r, c) for r in range(h0) for c in range(w0) if grid[r][c] == 1]
    r0, r1 = min(r for r, c in ones), max(r for r, c in ones)
    c0, c1 = min(c for r, c in ones), max(c for r, c in ones)
    canvas = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    h, w = len(canvas), len(canvas[0])

    outside = [(r, c, grid[r][c]) for r in range(h0) for c in range(w0)
               if grid[r][c] != 0 and not (r0 <= r <= r1 and c0 <= c <= c1)]

    if not outside:
        return canvas

    # The external markers specify where their matching colors should lie
    # relative to one another in the transformed rectangle.
    ext = {}
    for r, c, color in outside:
        ext[color] = (r, c)
    anchor = next((color for color in ext
                   if sum(v == color for row in canvas for v in row) == 1), None)

    transforms = [
        (lambda r, c: (r, c), h, w),
        (lambda r, c: (r, w - 1 - c), h, w),
        (lambda r, c: (h - 1 - r, c), h, w),
        (lambda r, c: (h - 1 - r, w - 1 - c), h, w),
        (lambda r, c: (c, r), w, h),
        (lambda r, c: (w - 1 - c, h - 1 - r), w, h),
        (lambda r, c: (c, h - 1 - r), w, h),
        (lambda r, c: (w - 1 - c, r), w, h),
    ]

    def sign(x):
        return (x > 0) - (x < 0)

    best = transforms[0]
    best_score = -1
    for mapping, oh, ow in transforms:
        score = 0
        if anchor is not None:
            ar, ac = ext[anchor]
            anchor_pos = next(( (r, c) for r in range(h) for c in range(w)
                               if canvas[r][c] == anchor), None)
            for color, (er, ec) in ext.items():
                if color == anchor:
                    continue
                pos = [(r, c) for r in range(h) for c in range(w) if canvas[r][c] == color]
                if len(pos) != 1 or anchor_pos is None:
                    continue
                tr, tc = mapping(*pos[0])
                tar, tac = mapping(*anchor_pos)
                if (sign(tr - tar), sign(tc - tac)) == (sign(er - ar), sign(ec - ac)):
                    score += 1
        if score > best_score:
            best_score = score
            best = (mapping, oh, ow)

    mapping, oh, ow = best
    out = [[1] * ow for _ in range(oh)]
    for r in range(h):
        for c in range(w):
            rr, cc = mapping(r, c)
            out[rr][cc] = canvas[r][c]
    return out
